import Mathlib

/-!
# Single-shadow Kruskal–Katona (the `i = 1` Lovász specialization)

This file derives the single-shadow specialization of the Kruskal–Katona theorem from the
Lovász form `Finset.kruskal_katona_lovasz_form` already in Mathlib.

## A note on the requested statement

The originally requested statement was

```
theorem kruskal_katona_single_shadow {α : Type*} [Fintype α] [DecidableEq α]
    {r k : ℕ} {𝒜 : Finset (Finset α)}
    (hr : ∀ s ∈ 𝒜, s.card = r)
    (hk : 𝒜.card ≥ k.choose r) :
    (shadow 𝒜).card ≥ k.choose (r - 1)
```

This statement is **false**. Counterexample: take `α := Fin 1`, `𝒜 := ∅`, `r := 1`, `k := 0`.
Then `hr` holds vacuously and `hk` reads `0 ≥ (0).choose 1 = 0`, which holds, yet the conclusion
reads `(∂ ∅).card = 0 ≥ (0).choose 0 = 1`, which is false. More generally the hypotheses are
satisfiable while the conclusion fails whenever `r = 0` or `r > k`.

The faithful (and true) statement, matching the `i = 1` case of the Lovász form, additionally
requires `1 ≤ r` and `r ≤ k`. These are exactly the instances of `i ≤ r` (with `i = 1`) and
`r ≤ k` appearing in `Finset.kruskal_katona_lovasz_form`. The remaining hypothesis `k ≤ n` of the
Lovász form is *derived* internally from `hk` together with the size bound, so it need not be
assumed.
-/

open Finset
open scoped FinsetFamily

namespace KruskalKatonaSingle

/-- If `1 ≤ r ≤ k` and `k.choose r ≤ n.choose r`, then `k ≤ n`.  (Strict monotonicity of the
binomial coefficient in its top argument, in contrapositive form.) -/
lemma le_of_choose_le_choose {r k n : ℕ} (hr : 1 ≤ r) (hrk : r ≤ k)
    (hc : k.choose r ≤ n.choose r) : k ≤ n := by
  contrapose! hc;
  induction hc <;> simp_all +decide;
  · cases r <;> simp_all +arith +decide [ Nat.choose ];
    exact Nat.choose_pos hrk;
  · cases hrk <;> simp_all +decide;
    · rw [ Nat.choose_eq_zero_of_lt ( by linarith ) ];
    · exact lt_of_lt_of_le ‹_› ( Nat.choose_le_succ _ _ )

/-- The shadow commutes with relabeling the ground set along an embedding. -/
lemma shadow_image_map {α β : Type*} [DecidableEq α] [DecidableEq β]
    (e : α ↪ β) (𝒜 : Finset (Finset α)) :
    ∂ (𝒜.image (Finset.map e)) = (∂ 𝒜).image (Finset.map e) := by
  ext t;
  simp +decide [ Finset.mem_shadow_iff_exists_mem_card_add_one, Finset.mem_image ];
  constructor;
  · rintro ⟨ a, ha, ht, ha' ⟩;
    obtain ⟨ u, hu, rfl ⟩ := Finset.subset_map_iff.mp ht;
    aesop;
  · grind +qlia

/-- **Single-shadow Kruskal–Katona theorem** (the `i = 1` case of the Lovász form).

If `𝒜` is a family of `r`-element subsets of a finite type with `1 ≤ r ≤ k` and
`k.choose r ≤ 𝒜.card`, then `k.choose (r - 1) ≤ (∂ 𝒜).card`. -/
theorem kruskal_katona_single_shadow {α : Type*} [Fintype α] [DecidableEq α]
    {r k : ℕ} {𝒜 : Finset (Finset α)}
    (hr1 : 1 ≤ r) (hrk : r ≤ k)
    (hr : ∀ s ∈ 𝒜, s.card = r)
    (hk : 𝒜.card ≥ k.choose r) :
    (shadow 𝒜).card ≥ k.choose (r - 1) := by
  by_contra h_contra;
  -- By the properties of the shadow and the Lovász form, we have:
  have h_shadow : (Finset.shadow (𝒜.image (Finset.map (Fintype.equivFin α).toEmbedding))).card ≥ k.choose (r - 1) := by
    apply_rules [ Finset.kruskal_katona_lovasz_form ];
    · apply le_of_choose_le_choose hr1 hrk;
      refine' le_trans hk _;
      exact le_trans ( Finset.card_le_card ( show 𝒜 ⊆ Finset.powersetCard r ( Finset.univ : Finset α ) from fun s hs => Finset.mem_powersetCard.mpr ⟨ Finset.subset_univ _, hr s hs ⟩ ) ) ( by simp +decide [ Finset.card_univ ] );
    · intro s hs; aesop;
    · rw [ Finset.card_image_of_injective _ fun x y hxy => by simpa using hxy ] ; aesop;
  rw [ shadow_image_map ] at h_shadow;
  exact h_contra ( h_shadow.trans ( Finset.card_image_le ) )

end KruskalKatonaSingle

